package com.sora.splineroads.world;
import com.sora.splineroads.core.*;import com.sora.splineroads.core.RoadGeometry.*;
import java.util.*;import java.nio.file.*;import net.minecraft.gametest.framework.*;import net.minecraft.nbt.*;import net.minecraftforge.gametest.*;
@GameTestHolder("splineroads_201_sign") @PrefixGameTestTemplate(false)
public final class JunctionSign201GameTests {
 @GameTest(template="empty",templateNamespace="splineroads_201_sign",timeoutTicks=24000)
 public static void actualThroughCurveSplitJunctionAdvanceSigns(GameTestHelper h)throws Exception{var level=h.getLevel();int fixture=0,total=0;
  for(boolean through:new boolean[]{true,false})for(boolean left:new boolean[]{false,true})for(boolean trees:new boolean[]{true,false}){double x=225000+fixture++*1000,y=-59.875,z=.5;var data=RoadData.get(level);var a=Curve201GameTests.marker(level,new Node(new V(x+.5,y,z),0,0));var b=Curve201GameTests.marker(level,new Node(new V(x+.5,y,z+300),0,0));
   var s=RoadLanes.configure(new Settings(Mode.CURVE,Style.O2_RAIL,9,1,.35,90).structure(Structure.GROUND),RoadProfile.Type.ORDINARY,new RoadLanes.Counts(3,3),4);s=s.options(s.options().sidewalk(RoadSidewalks.Config.DEFAULT.enabled(true)).streetscape(s.options().streetscape().planting(RoadStreetscape.Planting.CHERRY)).route(s.options().routing().fit(false).controls(List.of(new RoadProfile.Control(UUID.randomUUID(),new V(x+45.5,y,z+100)),new RoadProfile.Control(UUID.randomUUID(),new V(x+45.5,y,z+200)))).through(through)));
   s=s.options(s.options().traffic(left).streetscape(s.options().streetscape().planting(trees?RoadStreetscape.Planting.CHERRY:RoadStreetscape.Planting.NONE)));
   var whole=data.connect(level,null,a,b,s,null);var plan=RoadSplitter.plan(level,null,whole,whole.mesh().length()*.45,RoadSlicing.Connection.CONTINUOUS);RoadSplitter.commit(level,null,plan);var end=Curve201GameTests.marker(level,new Node(plan.pair().node().position().add(new V(left?60:150,0,0)),-90,0));
   var branch=RoadLanes.configure(new Settings(Mode.STRAIGHT,Style.O2_GREEN,9,1,.35,90).structure(Structure.GROUND),RoadProfile.Type.ORDINARY,new RoadLanes.Counts(3,3),4);branch=branch.options(branch.options().sidewalk(RoadSidewalks.Config.DEFAULT.enabled(true)).streetscape(branch.options().streetscape().planting(RoadStreetscape.Planting.CHERRY)));
   branch=branch.options(branch.options().traffic(left).streetscape(branch.options().streetscape().planting(trees?RoadStreetscape.Planting.CHERRY:RoadStreetscape.Planting.NONE)));
   var connected=data.connect(level,null,plan.pair().pos(),end,branch,null);data.smartSigns.refresh();for(int guard=0;guard<64&&data.smartSigns.sightlinesPending();guard++){data.smartSigns.advanceSightlines(level,Long.MAX_VALUE,8192);data.smartSigns.refresh();}
   var center=AutoJunctions.center(data,plan.pair().pos());h.assertTrue(center!=null,"actual connection did not create a junction");var id=center.getUUID("Id");
   if(left){var command=AutoJunctions.payload(level,null,id);command.getCompound("Spec").putBoolean("LeftTraffic",true);AutoJunctions.edit(level,null,command);data.smartSigns.refresh();for(int guard=0;guard<64&&data.smartSigns.sightlinesPending();guard++){data.smartSigns.advanceSightlines(level,Long.MAX_VALUE,8192);data.smartSigns.refresh();}}
   h.assertTrue(JunctionCodec.read(data.junctions.get(id).getCompound("Spec")).leftTraffic()==left,"fixture did not install requested junction traffic side");int count=0;var failures=new ArrayList<String>();
   for(var built:data.index.roads.values())if(id.equals(built.record.assembly())&&built.record.junction()!=null&&built.record.junction().get().arm()>=0){var sign=data.smartSigns.peek(new SmartSigns.Key(built.record.id(),0,1));count++;System.out.println("SR201 ACTUAL JUNCTION SIGN through="+through+" arm="+built.record.junction().get().arm()+" support="+sign.support()+" diagnostic="+sign.diagnostic());
    h.assertTrue(sign.support()==null||sign.support().paired()==left,"actual sign does not reflect requested traffic side");if(sign.support()==null||!sign.diagnostic().isEmpty()||sign.mode()!=SmartSigns.Mode.JUNCTION_ADVANCE){failures.add("arm="+built.record.junction().get().arm()+" "+sign.diagnostic());if(sign.support()!=null){var clean=sign.layout(sign.mode(),sign.target(),sign.branches(),"",sign.entry());for(var mount:SmartSigns.mountParts(built.mesh,clean))for(var other:data.index.roads.values())for(var part:other.record.structures())if(!ForkSignPlacement.mountingContact(mount,part,sign.support())&&RoadSolidOverlap.intersects(mount,part))System.out.println("SR201 SIGN COLLISION owner="+other.record.id()+" model="+part.model()+" material="+part.material()+" at="+part.a()+" part="+part+" mount="+mount);}}
   }
   long leaves=data.index.roads.values().stream().filter(r->r.mesh.first().center().x()>x-100&&r.mesh.first().center().x()<x+500).flatMap(r->r.record.structures().stream()).filter(p->p.material()==RoadStructures.Material.CHERRY_LEAVES).count();h.assertTrue(trees?leaves>0:leaves==0,"distant cherry planting was not preserved/config respected: "+leaves);System.out.println("SR201 JUNCTION PLANTING through="+through+" left="+left+" trees="+trees+" retainedCherryParts="+leaves);
   var disk=Path.of("junction-sign201-"+through+"-"+left+"-"+trees+".nbt");NbtIo.writeCompressed(data.save(new CompoundTag()),disk.toFile());h.assertTrue(count==3,"missing advance sign states: "+count);h.assertTrue(failures.isEmpty(),"missing actual signs: "+failures);total+=count;
   // A real saved structural obstacle must still hide a colliding sign; trees
   // avoiding its installation must never weaken the independent obstacle test.
   var owner=data.index.roads.values().stream().filter(r->id.equals(r.record.assembly())&&r.record.junction()!=null&&r.record.junction().get().arm()>=0).findFirst().orElseThrow();var key=new SmartSigns.Key(owner.record.id(),0,1);var state=data.smartSigns.peek(key);var foot=state.support().foot();var parts=new ArrayList<>(owner.record.structures());parts.add(new RoadStructures.Part(foot,foot,1,8,true,RoadStructures.Material.CONCRETE));data.index.put(new RoadIndex.Built(owner.record.structures(parts)));data.smartSigns.refresh();h.assertTrue(!data.smartSigns.peek(key).diagnostic().isEmpty(),"actual obstruction incorrectly exempted");data.index.put(owner);data.smartSigns.refresh();h.assertTrue(data.smartSigns.peek(key).diagnostic().isEmpty(),"removing obstruction did not restore sign");
   data=RoadData.load(NbtIo.readCompressed(disk.toFile()));level.getDataStorage().set("splineroads",data);checkSigns(h,data,id,"disk reload");var editable=data.editableRoad(connected.id());var edited=editable.settings().options(editable.settings().options().streetscape(editable.settings().options().streetscape().lampSpacing(32)));data.connect(level,null,editable.a(),editable.b(),edited,editable.id(),false);data.smartSigns.refresh();for(int guard=0;guard<64&&data.smartSigns.sightlinesPending();guard++){data.smartSigns.advanceSightlines(level,Long.MAX_VALUE,8192);data.smartSigns.refresh();}checkSigns(h,data,id,"explicit edit/save");
   System.out.println("SR201 JUNCTION SIGN LIFECYCLE PASS through="+through+" left="+left+" trees="+trees+" branchLength="+(left?60:150)+" build/obstacle-negative/disk-reload/edit-save");
  }h.assertTrue(total==24,"missing fixture coverage");h.assertTrue(RoadWorkChunks.heldCount(level)==0,"junction sign test leaked tickets");h.succeed();
 }
 static void checkSigns(GameTestHelper h,RoadData data,UUID group,String stage){data.smartSigns.refresh();int count=0;for(var r:data.index.roads.values())if(group.equals(r.record.assembly())&&r.record.junction()!=null&&r.record.junction().get().arm()>=0){var state=data.smartSigns.peek(new SmartSigns.Key(r.record.id(),0,1));h.assertTrue(state.support()!=null&&state.diagnostic().isEmpty(),stage+" sign invalid: "+state.diagnostic());h.assertTrue(state.support().paired()==r.record.junction().spec().leftTraffic(),stage+" sign traffic side changed");count++;}h.assertTrue(count==3,stage+" missing arms");}
}



